using var cts = new CancellationTokenSource(50);
var slow1 = Task.Delay(60_000).ContinueWith(_ => 1);
var slow2 = Task.Delay(60_000).ContinueWith(_ => 2);
var ex = await Cj.ThrowsAsync<OperationCanceledException>(() => Solution.RaceTask(slow1, slow2, cts.Token));
Cj.True(ex is not null, "external cancellation wins the race");

var fast = Task.FromResult(7);
var slow = new TaskCompletionSource<int>().Task;
Cj.Eq(await Solution.RaceTask(slow, fast, CancellationToken.None), 7, "completed task wins");
